1	"use server";
2	
3	/**
4	 * Game server control panel — server actions ("Manage" tab).
5	 *
6	 * Ownership-guarded (owner or admin), rate-limited wrappers around:
7	 *   - Power: start/stop/restart the game SERVICE (GAME_POWER job → worker).
8	 *   - Live console: tail logs (inline SSH read) + send an RCON/console command
9	 *     (inline SSH → SSH-tunnelled Source RCON, lib/game-control.ts).
10	 *   - Players: list + kick/ban over RCON (where the family supports it).
11	 *   - World/saves: list save entries, create a downloadable backup (GAME_BACKUP
12	 *     job), list existing backups (download via /api/files).
13	 *   - Scheduled restarts: CRUD over GameSchedule; the worker sweep fires them.
14	 *
15	 * Every value that reaches a shell/RCON is validated in lib/game-control.ts
16	 * (ports, paths, player ids, command lines). Root/RCON credentials never leave the
17	 * server and are never surfaced in an error. SANDBOX: inline reads return realistic
18	 * synthetic data; mutating jobs settle without touching a VM.
19	 */
20	import { revalidatePath } from "next/cache";
21	import { db } from "./db";
22	import { requireUser } from "./auth";
23	import { checkRateLimit } from "./rate-limit";
24	import { SANDBOX } from "./sandbox";
25	import { withServerSsh, exec } from "./ssh-exec";
26	import type { SftpServer } from "./sftp";
27	import { verifyCustomDomainDns, type DnsVerifyResult } from "./custom-domain-dns";
28	import {
29	  controlSpec,
30	  isGameFamily,
31	  isPowerAction,
32	  validateRconCommand,
33	  validatePlayerId,
34	  readGameLogs,
35	  readWorlds,
36	  readGameBackups,
37	  runRcon,
38	  parsePlayers,
39	  computeNextRun,
40	  type GameControlSpec,
41	  type Player,
42	  type WorldEntry,
43	  type BackupEntry,
44	} from "./game-control";
45	
46	type Result = { ok: true } | { ok: false; error: string };
47	
48	/** Jobs that must not overlap a control-panel mutation on the same server. */
49	const EXCLUSIVE_JOBS = [
50	  "PROVISION",
51	  "REINSTALL",
52	  "DELETE",
53	  "RESIZE",
54	  "SUSPEND",
55	  "UNSUSPEND",
56	  "SNAPSHOT_ROLLBACK",
57	  "BACKUP_RESTORE",
58	  "DISK_EXPAND",
59	] as const;
60	
61	async function ownedServer(serverId: string) {
62	  const user = await requireUser();
63	  const server = await db.server.findUnique({
64	    where: { id: serverId },
65	    select: {
66	      id: true,
67	      userId: true,
68	      status: true,
69	      hostname: true,
70	      rootPassword: true,
71	      rootPasswordEnc: true,
72	      sshPort: true,
73	      dedicatedIp: { select: { address: true } },
74	      osTemplate: { select: { family: true } },
75	      gamePlan: { select: { gameFamily: true } },
76	    },
77	  });
78	  if (!server) throw new Error("Not found");
79	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
80	  return { user, server };
81	}
82	
83	/** Resolve the game family (game plan first, then OS template) if it is a game. */
84	function resolveFamily(server: {
85	  osTemplate?: { family?: string | null } | null;
86	  gamePlan?: { gameFamily?: string | null } | null;
87	}): string | null {
88	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
89	  return isGameFamily(fam) ? fam : null;
90	}
91	
92	function requireSpec(server: Parameters<typeof resolveFamily>[0]): GameControlSpec {
93	  const family = resolveFamily(server);
94	  const spec = controlSpec(family);
95	  if (!spec) throw new Error("This server is not a supported game server.");
96	  return spec;
97	}
98	
99	function throttle(userId: string, op: string, max: number): string | null {
100	  const rl = checkRateLimit(`gamectl:${op}:${userId}`, { max, windowMs: 60_000 });
101	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
102	}
103	
104	async function lifecycleBusy(serverId: string): Promise<boolean> {
105	  const n = await db.job.count({
106	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
107	  });
108	  return n > 0;
109	}
110	
111	async function gameJobInflight(serverId: string): Promise<boolean> {
112	  const n = await db.job.count({
113	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: ["GAME_POWER", "GAME_BACKUP"] as any } },
114	  });
115	  return n > 0;
116	}
117	
118	/** Never surface credentials or internal detail in a customer-facing error. */
119	function safeError(err: unknown): string {
120	  const msg = err instanceof Error ? err.message : String(err);
121	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
122	  if (/not a supported game server|not enabled|not available|not running|in progress/i.test(msg)) return msg.slice(0, 200);
123	  if (/timed out|reachable|root password/i.test(msg)) return msg.slice(0, 200);
124	  return "Could not reach the game server. Please try again shortly.";
125	}
