127	// ---------------------------------------------------------------------------
128	// Overview (capabilities the UI renders from)
129	// ---------------------------------------------------------------------------
130	
131	export type GameManageView = {
132	  family: string;
133	  label: string;
134	  rconSupported: boolean;
135	  rconNote: string | null;
136	  listSupported: boolean;
137	  running: boolean;
138	};
139	
140	export async function getGameManage(
141	  serverId: string
142	): Promise<{ ok: true; view: GameManageView } | { ok: false; error: string }> {
143	  try {
144	    const { server } = await ownedServer(serverId);
145	    const spec = requireSpec(server);
146	    const rconSupported = spec.rcon === "source";
147	    const rconNote =
148	      spec.rcon === "rust-web"
149	        ? "Rust uses WebSocket RCON, which is not wired yet — power, logs, schedules and world backups are fully available."
150	        : spec.rcon === "none"
151	          ? `${spec.label} has no remote console protocol, so the command box is disabled — power, logs, schedules and world backups still work.`
152	          : null;
153	    return {
154	      ok: true,
155	      view: {
156	        family: spec.family,
157	        label: spec.label,
158	        rconSupported,
159	        rconNote,
160	        listSupported: rconSupported && !!spec.listCommand,
161	        running: server.status === "RUNNING",
162	      },
163	    };
164	  } catch (err) {
165	    return { ok: false, error: safeError(err) };
166	  }
167	}
