169	// ---------------------------------------------------------------------------
170	// Power (GAME_POWER job)
171	// ---------------------------------------------------------------------------
172	
173	export async function gamePower(serverId: string, action: string): Promise<Result> {
174	  try {
175	    const { user, server } = await ownedServer(serverId);
176	    requireSpec(server);
177	    if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
178	    const limited = throttle(user.id, "power", 20);
179	    if (limited) return { ok: false, error: limited };
180	    if (server.status !== "RUNNING")
181	      return { ok: false, error: "The VM must be running to control the game service." };
182	    if (await lifecycleBusy(server.id))
183	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
184	    if (await gameJobInflight(server.id))
185	      return { ok: false, error: "A game control action is already in progress on this server." };
186	
187	    await db.job.create({
188	      data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: action === "restart" } },
189	    });
190	    await db.auditLog.create({
191	      data: { userId: user.id, action: "gameserver.power", detail: `${action} on ${server.hostname}` },
192	    });
193	    revalidatePath(`/dashboard/servers/${serverId}`);
194	    return { ok: true };
195	  } catch (err) {
196	    return { ok: false, error: safeError(err) };
197	  }
198	}
