200	// ---------------------------------------------------------------------------
201	// Live console: logs (inline read) + RCON command
202	// ---------------------------------------------------------------------------
203	
204	export async function getGameLogs(
205	  serverId: string
206	): Promise<{ ok: true; lines: string[]; unit: string | null } | { ok: false; error: string }> {
207	  try {
208	    const { user, server } = await ownedServer(serverId);
209	    const spec = requireSpec(server);
210	    const limited = throttle(user.id, "logs", 40);
211	    if (limited) return { ok: false, error: limited };
212	    if (SANDBOX) {
213	      return {
214	        ok: true,
215	        unit: spec.serviceHints[0],
216	        lines: [
217	          `[${new Date().toISOString()}] [Server thread/INFO]: Starting ${spec.label} server`,
218	          `[${new Date().toISOString()}] [Server thread/INFO]: Loading world`,
219	          `[${new Date().toISOString()}] [Server thread/INFO]: Done — sandbox synthetic log (no VM was contacted).`,
220	        ],
221	      };
222	    }
223	    if (server.status !== "RUNNING")
224	      return { ok: false, error: "Logs are available only while the server is running." };
225	    const res = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec));
226	    return res.ok ? { ok: true, lines: res.lines, unit: res.unit } : { ok: false, error: res.error };
227	  } catch (err) {
228	    return { ok: false, error: safeError(err) };
229	  }
230	}
231	
232	export async function sendGameCommand(
233	  serverId: string,
234	  command: string
235	): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
236	  try {
237	    const { user, server } = await ownedServer(serverId);
238	    const spec = requireSpec(server);
239	    if (spec.rcon !== "source")
240	      return { ok: false, error: `Remote console commands are not available for ${spec.label}.` };
241	    const valid = validateRconCommand(command);
242	    if (!valid.ok) return { ok: false, error: valid.error };
243	    const limited = throttle(user.id, "rcon", 30);
244	    if (limited) return { ok: false, error: limited };
245	
246	    if (SANDBOX) return { ok: true, response: `(sandbox) ran: ${valid.command}` };
247	    if (server.status !== "RUNNING")
248	      return { ok: false, error: "The server must be running to send console commands." };
249	
250	    await db.auditLog.create({
251	      data: { userId: user.id, action: "gameserver.rcon", detail: `${spec.family}: ${valid.command.slice(0, 120)}` },
252	    });
253	    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, valid.command));
254	    return res.ok ? { ok: true, response: res.response } : { ok: false, error: res.error };
255	  } catch (err) {
256	    return { ok: false, error: safeError(err) };
257	  }
258	}
