260	// ---------------------------------------------------------------------------
261	// Players (RCON list / kick / ban)
262	// ---------------------------------------------------------------------------
263	
264	export async function getGamePlayers(
265	  serverId: string
266	): Promise<{ ok: true; players: Player[]; raw: string } | { ok: false; error: string }> {
267	  try {
268	    const { user, server } = await ownedServer(serverId);
269	    const spec = requireSpec(server);
270	    if (spec.rcon !== "source" || !spec.listCommand)
271	      return { ok: false, error: `Player list is not available for ${spec.label}.` };
272	    const limited = throttle(user.id, "players", 40);
273	    if (limited) return { ok: false, error: limited };
274	    if (SANDBOX)
275	      return { ok: true, players: [{ name: "steve" }, { name: "alex" }], raw: "There are 2 of a max of 20 players online: steve, alex" };
276	    if (server.status !== "RUNNING")
277	      return { ok: false, error: "The player list is available only while the server is running." };
278	    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, spec.listCommand!));
279	    if (!res.ok) return { ok: false, error: res.error };
280	    const parsed = parsePlayers(spec.family, res.response);
281	    return { ok: true, players: parsed.players, raw: parsed.raw };
282	  } catch (err) {
283	    return { ok: false, error: safeError(err) };
284	  }
285	}
