287	async function playerAction(serverId: string, playerId: string, kind: "kick" | "ban"): Promise<Result> {
288	  try {
289	    const { user, server } = await ownedServer(serverId);
290	    const spec = requireSpec(server);
291	    const template = kind === "kick" ? spec.kickCommand : spec.banCommand;
292	    if (spec.rcon !== "source" || !template)
293	      return { ok: false, error: `${kind === "kick" ? "Kick" : "Ban"} is not available for ${spec.label}.` };
294	    const valid = validatePlayerId(playerId);
295	    if (!valid.ok) return { ok: false, error: valid.error };
296	    const limited = throttle(user.id, "player-action", 20);
297	    if (limited) return { ok: false, error: limited };
298	    if (SANDBOX) return { ok: true };
299	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
300	
301	    const command = template.replace("%s", valid.id);
302	    await db.auditLog.create({
303	      data: { userId: user.id, action: `gameserver.${kind}`, detail: `${spec.family}: ${valid.id}` },
304	    });
305	    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
306	    return res.ok ? { ok: true } : { ok: false, error: res.error };
307	  } catch (err) {
308	    return { ok: false, error: safeError(err) };
309	  }
310	}
