338	// ---------------------------------------------------------------------------
339	// Operators / Whitelist / Bans / Gamemode / Inventory (Minecraft management)
340	// ---------------------------------------------------------------------------
341	
342	const MC_PLAYER_RE = /^[A-Za-z0-9_]{3,16}$/;
343	
344	function validMcName(name: string): { ok: true; name: string } | { ok: false; error: string } {
345	  const trimmed = name.trim();
346	  if (!MC_PLAYER_RE.test(trimmed)) return { ok: false, error: "Invalid Minecraft username (3-16 chars, letters/digits/underscore)." };
347	  return { ok: true, name: trimmed };
348	}
349	
350	function stripAnsi(s: string): string {
351	  return s.replace(/\x1b\[[0-9;]*m/g, "");
352	}
353	
354	async function mcRcon(serverId: string, command: string, auditAction: string, auditDetail: string): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
355	  const { user, server } = await ownedServer(serverId);
356	  const spec = requireSpec(server);
357	  if (spec.family !== "minecraft") return { ok: false, error: "This feature is only available for Minecraft servers." };
358	  if (spec.rcon !== "source") return { ok: false, error: "RCON is not available for this server." };
359	  const limited = throttle(user.id, "mc-mgmt", 30);
360	  if (limited) return { ok: false, error: limited };
361	  if (SANDBOX) return { ok: true, response: `(sandbox) ${command}` };
362	  if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
363	  await db.auditLog.create({ data: { userId: user.id, action: auditAction, detail: auditDetail } });
364	  const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
365	  return res.ok ? { ok: true, response: stripAnsi(res.response) } : { ok: false, error: res.error };
366	}
