368	export async function addGameOperator(serverId: string, playerName: string): Promise<Result> {
369	  try {
370	    const v = validMcName(playerName);
371	    if (!v.ok) return v;
372	    const r = await mcRcon(serverId, `op ${v.name}`, "gameserver.op", v.name);
373	    return r.ok ? { ok: true } : r;
374	  } catch (err) { return { ok: false, error: safeError(err) }; }
375	}
