386	export async function listGameOperators(serverId: string): Promise<{ ok: true; operators: string[] } | { ok: false; error: string }> {
387	  try {
388	    const { user, server } = await ownedServer(serverId);
389	    const spec = requireSpec(server);
390	    if (spec.family !== "minecraft") return { ok: false, error: "Operators are only available for Minecraft." };
391	    const limited = throttle(user.id, "mc-mgmt", 30);
392	    if (limited) return { ok: false, error: limited };
393	    if (SANDBOX) return { ok: true, operators: ["Steve", "Alex"] };
394	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
395	    const res = await withServerSsh(server as SftpServer, async (conn) => {
396	      const sshExec = exec;
397	      const roots = spec.dataRoots.map((r) => `${r}/ops.json`).join(" ");
398	      const { stdout } = await sshExec(conn, `for f in ${roots}; do [ -f "$f" ] && cat "$f" && exit 0; done; echo "[]"`, 5000);
399	      return stdout.trim();
400	    });
401	    try {
402	      const arr = JSON.parse(res);
403	      return { ok: true, operators: Array.isArray(arr) ? arr.map((e: any) => e.name || e).filter(Boolean) : [] };
404	    } catch {
405	      return { ok: true, operators: [] };
406	    }
407	  } catch (err) { return { ok: false, error: safeError(err) }; }
408	}
