793	import { createHash } from "node:crypto";
794	import { isGateableCommandNode, FREEMC_GATEABLE_COMMANDS } from "./freemc-command-catalog";
795	
796	const ROLE_NAME_RE = /^[a-z][a-z0-9_]{2,19}$/;
