799	function offlineUuidFor(name: string): string {
800	  const hash = createHash("md5").update(`OfflinePlayer:${name}`, "utf8").digest();
801	  hash[6] = (hash[6] & 0x0f) | 0x30;
802	  hash[8] = (hash[8] & 0x3f) | 0x80;
803	  const hex = hash.toString("hex");
804	  return [hex.slice(0, 8), hex.slice(8, 12), hex.slice(12, 16), hex.slice(16, 20), hex.slice(20)].join("-");
805	}
806	
807	type ParsedLpFile = { name: string | null; uuid: string | null; permissions: string[]; parents: string[] };
808	
809	function parseLuckPermsFile(text: string): ParsedLpFile {
810	  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
811	  let name: string | null = null;
812	  let uuid: string | null = null;
813	  const permissions: string[] = [];
814	  const parents: string[] = [];
815	  let section: "none" | "permissions" | "parents" = "none";
816	  for (let i = 0; i < lines.length; i++) {
817	    const line = lines[i];
818	    if (line === "") continue;
819	    const isTopLevelKey = /^[A-Za-z-]+:/.test(line);
820	    if (isTopLevelKey) {
821	      if (/^name:/.test(line)) name = line.slice(5).trim().replace(/^'(.*)'$/, "$1");
822	      else if (/^uuid:/.test(line)) uuid = line.slice(5).trim();
823	      section = /^permissions:\s*$/.test(line) ? "permissions" : /^parents:\s*$/.test(line) ? "parents" : "none";
824	      continue;
825	    }
826	    const negatedHead = line.match(/^-\s+(\S+):\s*$/);
827	    const bare = line.match(/^-\s+(\S+)\s*$/);
828	    if (section === "permissions") {
829	      if (negatedHead) {
830	        const next = lines[i + 1] ?? "";
831	        const valMatch = next.match(/^\s+value:\s*(true|false)\s*$/);
832	        if (valMatch) i++;
833	        if (valMatch?.[1] === "true") permissions.push(negatedHead[1]);
834	      } else if (bare) {
835	        permissions.push(bare[1]);
836	      }
837	    } else if (section === "parents" && bare) {
838	      parents.push(bare[1]);
839	    }
840	  }
841	  return { name, uuid, permissions, parents };
842	}
