844	async function readVmLpStorageDir(
845	  sshConn: Parameters<typeof exec>[0],
846	  dir: string,
847	): Promise<{ key: string; text: string }[]> {
848	  const MARK = "===GAME_ROLES_FILE:";
849	  const cmd =
850	    `d=${JSON.stringify(dir)}; [ -d "$d" ] || exit 0; for f in "$d"/*.yml; do [ -f "$f" ] || continue; ` +
851	    `echo "${MARK}$(basename "$f" .yml)==="; cat "$f"; done`;
852	  const r = await exec(sshConn, cmd, 15_000);
853	  if (r.code !== 0 || !r.stdout.trim()) return [];
854	  const out: { key: string; text: string }[] = [];
855	  const parts = r.stdout.split(new RegExp(`^${MARK}(.+?)===$`, "m"));
856	  for (let i = 1; i < parts.length; i += 2) {
857	    out.push({ key: parts[i], text: parts[i + 1] ?? "" });
858	  }
859	  return out;
860	}
