887	    const res = await withServerSsh(server as SftpServer, async (conn) => {
888	      const pluginsRes = await runRcon(conn, spec, "plugins");
889	      if (!pluginsRes.ok) return { installed: false, hasYamlStorage: false };
890	      const installed = /luckperms/i.test(stripAnsi(pluginsRes.response));
891	      if (!installed) return { installed: false, hasYamlStorage: false };
892	      const lpDir = await findLpDir(conn, spec);
893	      if (!lpDir) return { installed: true, hasYamlStorage: false };
894	      const configRead = await exec(conn, `cat ${JSON.stringify(lpDir + "/config.yml")} 2>/dev/null`, 5_000);
895	      const hasYaml = /^storage-method:\s*yaml\s*$/m.test(configRead.stdout);
896	      return { installed: true, hasYamlStorage: hasYaml };
897	    });
