902	export async function ensureGameLpYamlStorage(
903	  serverId: string
904	): Promise<Result> {
905	  try {
906	    const { user, server } = await ownedServer(serverId);
907	    const spec = requireSpec(server);
908	    if (spec.family !== "minecraft") return { ok: false, error: "Roles are only available for Minecraft." };
909	    if (SANDBOX) return { ok: true };
910	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
911	    const res = await withServerSsh(server as SftpServer, async (conn) => {
912	      const lpDir = await findLpDir(conn, spec);
913	      if (!lpDir) return { ok: false as const, error: "LuckPerms not found. Install it from the Plugins tab first." };
914	      const configPath = `${lpDir}/config.yml`;
915	      const configRead = await exec(conn, `cat ${JSON.stringify(configPath)}`, 5_000);
916	      if (configRead.code !== 0) return { ok: false as const, error: "Can't read LuckPerms config." };
917	      const hasYaml = /^storage-method:\s*yaml\s*$/m.test(configRead.stdout);
918	      const hasUuidCache = /^use-server-uuid-cache:\s*true\s*$/m.test(configRead.stdout);
919	      if (hasYaml && hasUuidCache) return { ok: true as const };
