1021	/**
1022	 * Valid hostname: letters, digits, hyphens, dots. No protocol, no path, no IP,
1023	 * at least 4 chars (shortest: a.co). Max 253 chars per RFC 1035.
1024	 */
1025	const HOSTNAME_RE = /^(?!.*\.\.)(?!-)[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}$/;
1026	const IP_RE = /^\d{1,3}(\.\d{1,3}){3}$/;
1027	
1028	function cleanDomain(raw: string): string {
1029	  let d = raw.trim().toLowerCase();
1030	  // Strip protocol prefix if someone pastes a URL
1031	  d = d.replace(/^https?:\/\//i, "");
1032	  // Strip trailing slash / path
1033	  d = d.replace(/\/.*$/, "");
1034	  return d;
1035	}
1036	
1037	function validateDomain(raw: string): { ok: true; domain: string } | { ok: false; error: string } {
1038	  const domain = cleanDomain(raw);
1039	  if (domain.length < 4) return { ok: false, error: "Domain is too short." };
1040	  if (domain.length > 253) return { ok: false, error: "Domain is too long." };
1041	  if (IP_RE.test(domain)) return { ok: false, error: "Enter a domain name, not an IP address." };
1042	  if (!HOSTNAME_RE.test(domain)) return { ok: false, error: "Invalid domain format. Example: play.mydomain.com" };
1043	  return { ok: true, domain };
1044	}
