1046	/** Resolve the effective public IP and game port for a server. */
1047	async function serverConnectInfo(serverId: string): Promise<{ ip: string; port: number } | null> {
1048	  const s = await db.server.findUnique({
1049	    where: { id: serverId },
1050	    select: {
1051	      dedicatedIp: { select: { address: true } },
1052	      portForwards: { orderBy: { publicPort: "asc" } },
1053	    },
1054	  });
1055	  if (!s) return null;
1056	
1057	  const publicIp = process.env.PUBLIC_IP ?? "";
1058	
1059	  if (s.dedicatedIp) {
1060	    // Dedicated IP uses the default Minecraft port (25565)
1061	    const pf = s.portForwards[0];
1062	    return { ip: s.dedicatedIp.address, port: pf?.guestPort ?? 25565 };
1063	  }
1064	
1065	  if (s.portForwards.length > 0) {
1066	    return { ip: publicIp, port: s.portForwards[0].publicPort };
1067	  }
1068	
1069	  return publicIp ? { ip: publicIp, port: 25565 } : null;
1070	}
