1080	export async function setCustomDomain(
1081	  serverId: string,
1082	  domain: string | null,
1083	): Promise<SetCustomDomainResult> {
1084	  try {
1085	    const { user } = await ownedServer(serverId);
1086	    const rl = throttle(user.id, "customDomain", 10);
1087	    if (rl) return { ok: false, error: rl };
1088	
1089	    if (domain === null || domain.trim() === "") {
1090	      // Clear the custom domain
1091	      await db.server.update({
1092	        where: { id: serverId },
1093	        data: { customDomain: null, customDomainVerified: false },
1094	      });
1095	      revalidatePath(`/dashboard/servers/${serverId}`);
1096	      return { ok: true, domain: null };
1097	    }
1098	
1099	    const v = validateDomain(domain);
1100	    if (!v.ok) return { ok: false, error: v.error };
1101	
1102	    // Check if another server already uses this domain
1103	    const existing = await db.server.findFirst({
1104	      where: { customDomain: v.domain, id: { not: serverId } },
1105	      select: { id: true },
1106	    });
1107	    if (existing) return { ok: false, error: "This domain is already in use on another server." };
1108	
1109	    await db.server.update({
1110	      where: { id: serverId },
1111	      data: { customDomain: v.domain, customDomainVerified: false },
1112	    });
1113	    revalidatePath(`/dashboard/servers/${serverId}`);
1114	    return { ok: true, domain: v.domain };
1115	  } catch (err) {
1116	    return { ok: false, error: safeError(err) };
1117	  }
