1124	/**
1125	 * Verify that the customer's DNS records are correctly configured for their
1126	 * custom domain. Updates customDomainVerified if both A and SRV pass.
1127	 */
1128	export async function verifyCustomDomain(
1129	  serverId: string,
1130	): Promise<VerifyCustomDomainResult> {
1131	  try {
1132	    const { user } = await ownedServer(serverId);
1133	    const rl = throttle(user.id, "customDomainVerify", 6);
1134	    if (rl) return { ok: false, error: rl };
1135	
1136	    const server = await db.server.findUnique({
1137	      where: { id: serverId },
1138	      select: { customDomain: true },
1139	    });
1140	    if (!server?.customDomain) {
