1147	    }
1148	
1149	    const dns = await verifyCustomDomainDns(server.customDomain, info.ip, info.port);
1150	    const verified = dns.aOk && dns.srvOk;
1151	
1152	    await db.server.update({
1153	      where: { id: serverId },
1154	      data: { customDomainVerified: verified },
1155	    });
1156	
1157	    revalidatePath(`/dashboard/servers/${serverId}`);
1158	    return { ok: true, verified, dns, expectedIp: info.ip, expectedPort: info.port };
