1185	    const { server } = await ownedServer(serverId);
1186	    const limit = Math.min(opts?.limit ?? 100, 200);
1187	    const offset = opts?.offset ?? 0;
1188	    const where: any = { serverId: server.id };
1189	    if (opts?.playerName) {
1190	      where.playerName = { contains: opts.playerName, mode: "insensitive" };
1191	    }
1192	
1193	    const [sessions, total] = await Promise.all([
1194	      db.playerSession.findMany({
1195	        where,
1196	        orderBy: { joinedAt: "desc" },
1197	        take: limit,
1198	        skip: offset,
1199	      }),
1200	      db.playerSession.count({ where }),
1201	    ]);
1202	
1203	    return {
1204	      ok: true,
1205	      total,
1206	      sessions: sessions.map((s) => ({
1207	        id: s.id,
1208	        playerName: s.playerName,
1209	        joinedAt: s.joinedAt.toISOString(),
1210	        leftAt: s.leftAt?.toISOString() ?? null,
1211	        durationMs: s.leftAt
1212	          ? s.leftAt.getTime() - s.joinedAt.getTime()
1213	          : null,
1214	      })),
1215	    };
1216	  } catch (err) {
1217	    return { ok: false, error: safeError(err) };
