1221	export type PlayerStatsResult =
1222	  | {
1223	      ok: true;
1224	      uniquePlayers: number;
1225	      totalPlaytimeMs: number;
1226	      avgSessionMs: number;
1227	      currentOnline: number;
1228	      topPlayers: { name: string; totalMs: number; sessions: number }[];
1229	    }
1230	  | { ok: false; error: string };
1231	
1232	export async function getPlayerStats(serverId: string): Promise<PlayerStatsResult> {
1233	  try {
1234	    const { server } = await ownedServer(serverId);
1235	
1236	    const [allSessions, currentOnline] = await Promise.all([
1237	      db.playerSession.findMany({
1238	        where: { serverId: server.id },
1239	        select: { playerName: true, joinedAt: true, leftAt: true },
1240	      }),
1241	      db.playerSession.count({
1242	        where: { serverId: server.id, leftAt: null },
1243	      }),
1244	    ]);
1245	
1246	    const playerMap = new Map<string, { totalMs: number; sessions: number }>();
1247	    let totalPlaytimeMs = 0;
1248	    let completedSessions = 0;
1249	
1250	    for (const s of allSessions) {
1251	      const ms = s.leftAt
1252	        ? s.leftAt.getTime() - s.joinedAt.getTime()
1253	        : Date.now() - s.joinedAt.getTime();
1254	      totalPlaytimeMs += ms;
1255	      if (s.leftAt) completedSessions++;
1256	
1257	      const key = s.playerName.toLowerCase();
1258	      const existing = playerMap.get(key) ?? { totalMs: 0, sessions: 0 };
1259	      existing.totalMs += ms;
1260	      existing.sessions += 1;
1261	      playerMap.set(key, existing);
1262	    }
1263	
1264	    // Preserve original casing for display: use the first-seen casing
1265	    const nameCasing = new Map<string, string>();
1266	    for (const s of allSessions) {
1267	      const key = s.playerName.toLowerCase();
1268	      if (!nameCasing.has(key)) nameCasing.set(key, s.playerName);
1269	    }
1270	
1271	    const topPlayers = [...playerMap.entries()]
1272	      .sort((a, b) => b[1].totalMs - a[1].totalMs)
1273	      .slice(0, 10)
1274	      .map(([key, data]) => ({
1275	        name: nameCasing.get(key) ?? key,
1276	        totalMs: data.totalMs,
1277	        sessions: data.sessions,
1278	      }));
1279	
1280	    return {
1281	      ok: true,
1282	      uniquePlayers: playerMap.size,
1283	      totalPlaytimeMs,
1284	      avgSessionMs: completedSessions > 0 ? Math.round(totalPlaytimeMs / allSessions.length) : 0,
1285	      currentOnline,
1286	      topPlayers,
1287	    };
1288	  } catch (err) {
1289	    return { ok: false, error: safeError(err) };
1290	  }
1291	}
