64	function fmtUptime(seconds: number): string {
65	  if (!seconds || seconds <= 0) return "—";
66	  const d = Math.floor(seconds / 86400);
67	  const h = Math.floor((seconds % 86400) / 3600);
68	  const m = Math.floor((seconds % 3600) / 60);
69	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
70	}
