export type GameModePresetInfo = {
  id: string;
  name: string;
  description: string;
  icon: string;
  rconCommands: string[];
  configKeys: string[];
};

/** Return the list of presets (no secret/internal data — safe for the client). */
export function getGameModePresets(): GameModePresetInfo[] {
  return GAME_MODE_PRESETS.map((p) => ({
    id: p.id,
    name: p.name,
    description: p.description,
    icon: p.icon,
    rconCommands: p.rconCommands,
    configKeys: Object.keys(p.configPatch),
  }));
}

export type ApplyPresetResult =
  | { ok: true; applied: string[]; failed: string[] }
  | { ok: false; error: string };

/**
 * Apply a game-mode preset to a Minecraft server:
 *  1. Runs RCON commands (gamerules, difficulty, defaultgamemode) for immediate effect.
 *  2. Patches the stored gameConfig and enqueues a GAME_CONFIG job so the
 *     server.properties changes survive restarts.
 */
export async function applyGameModePreset(
  serverId: string,
  presetId: string,
): Promise<ApplyPresetResult> {
  try {
    const preset = GAME_MODE_PRESETS.find((p) => p.id === presetId);
    if (!preset) return { ok: false, error: "Unknown preset." };

    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.family !== "minecraft")
      return { ok: false, error: "Game mode presets are only available for Minecraft servers." };
    if (spec.rcon !== "source")
      return { ok: false, error: "RCON is not available for this server." };
    const limited = throttle(user.id, "mc-mgmt", 30);
    if (limited) return { ok: false, error: limited };

    // --- 1. RCON commands (immediate) ---
    const applied: string[] = [];
    const failed: string[] = [];

    if (SANDBOX) {
      // In sandbox, pretend everything succeeded.
      for (const cmd of preset.rconCommands) applied.push(cmd);
    } else {
      if (server.status !== "RUNNING")
        return { ok: false, error: "The server must be running to apply a preset." };

      await withServerSsh(server as SftpServer, async (conn) => {
        for (const cmd of preset.rconCommands) {
          const res = await runRcon(conn, spec, cmd);
          if (res.ok) applied.push(cmd);
          else failed.push(cmd);
        }
      });
    }

    // --- 2. Persist server.properties changes ---
    const existing = (server as any).gameConfig as Record<string, unknown> | null;
    const merged = { ...(existing ?? {}), ...preset.configPatch };

    await db.server.update({
      where: { id: server.id },
      data: { gameConfig: merged as any },
    });
    await db.job.create({ data: { type: "GAME_CONFIG" as any, serverId: server.id } });

    await db.auditLog.create({
      data: {
        userId: user.id,
        action: "gameserver.preset",
        detail: `${preset.name} (${preset.id}) on ${server.hostname}`,
      },
    });

    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, applied, failed };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

