"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  getGameModePresets,
  applyGameModePreset,
  type GameModePresetInfo,
} from "@/lib/actions-game-control";

const PRESETS = getGameModePresets();

function PresetCard({
  preset,
  running,
  onSetup,
}: {
  preset: GameModePresetInfo;
  running: boolean;
  onSetup: (id: string) => void;
}) {
  return (
    <div className="group relative flex flex-col rounded-xl border border-white/[0.06] bg-navy-900/60 p-4 transition-colors hover:border-brand-500/30 hover:bg-navy-900/80">
      <div className="mb-2 text-2xl">{preset.icon}</div>
      <h4 className="text-sm font-semibold text-slate-100">{preset.name}</h4>
      <p className="mt-1 flex-1 text-xs leading-relaxed text-slate-400">
        {preset.description}
      </p>
      <button
        type="button"
        disabled={!running}
        onClick={() => onSetup(preset.id)}
        className="mt-3 w-full rounded-lg bg-brand-500/20 px-3 py-1.5 text-xs font-semibold text-brand-300 transition-colors hover:bg-brand-500/30 disabled:cursor-not-allowed disabled:opacity-40"
      >
        Setup
      </button>
    </div>
  );
}

export function GameModePresets({
  serverId,
  running,
}: {
  serverId: string;
  running: boolean;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [confirm, setConfirm] = useState<GameModePresetInfo | null>(null);
  const [result, setResult] = useState<{
    preset: string;
    applied: string[];
    failed: string[];
  } | null>(null);
  const [error, setError] = useState<string | null>(null);

  function handleSetup(id: string) {
    const preset = PRESETS.find((p) => p.id === id);
    if (preset) {
      setConfirm(preset);
      setResult(null);
      setError(null);
    }
  }

  function handleApply() {
    if (!confirm) return;
    const presetId = confirm.id;
    const presetName = confirm.name;
    setConfirm(null);

    start(async () => {
      setError(null);
      setResult(null);
      const res = await applyGameModePreset(serverId, presetId);
      if (res.ok) {
        setResult({ preset: presetName, applied: res.applied, failed: res.failed });
        router.refresh();
      } else {
        setError(res.error);
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center gap-2">
        <h3 className="font-semibold">Game Mode Presets</h3>
        <span className="rounded-full border border-brand-500/25 bg-brand-500/[0.08] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-300">
          one-click
        </span>
      </div>
      <p className="mb-4 max-w-2xl text-sm text-slate-400">
        Apply a game type preset to instantly configure game rules and server settings.
        This changes game rules and server settings. It does{" "}
        <strong className="text-slate-300">not</strong> install plugins — install
        plugins from the <span className="text-slate-200">Plugins</span> tab for the
        full experience.
      </p>

      {/* Preset grid */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
        {PRESETS.map((p) => (
          <PresetCard
            key={p.id}
            preset={p}
            running={running}
            onSetup={handleSetup}
          />
        ))}
      </div>

      {!running && (
        <p className="mt-3 text-xs text-amber-400/80">
          Start your server to apply a preset.
        </p>
      )}

      {/* Pending indicator */}
      {pending && (
        <div className="mt-4 flex items-center gap-2 rounded-lg border border-brand-500/20 bg-brand-500/[0.06] px-4 py-3 text-sm text-brand-300">
          <svg
            className="h-4 w-4 animate-spin"
            viewBox="0 0 24 24"
            fill="none"
          >
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            />
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
            />
          </svg>
          Applying preset...
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="mt-4 rounded-lg border border-red-500/20 bg-red-500/[0.06] px-4 py-3 text-sm text-red-300">
          {error}
        </div>
      )}

      {/* Success */}
      {result && (
        <div className="mt-4 rounded-lg border border-emerald-500/20 bg-emerald-500/[0.06] px-4 py-3 text-sm">
          <p className="font-medium text-emerald-300">
            {result.preset} preset applied successfully.
          </p>
          {result.applied.length > 0 && (
            <div className="mt-2">
              <p className="text-xs font-medium text-emerald-400/80">
                Applied ({result.applied.length}):
              </p>
              <ul className="mt-1 space-y-0.5">
                {result.applied.map((cmd, i) => (
                  <li
                    key={i}
                    className="font-mono text-xs text-emerald-300/70"
                  >
                    /{cmd}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {result.failed.length > 0 && (
            <div className="mt-2">
              <p className="text-xs font-medium text-amber-400/80">
                Failed ({result.failed.length}):
              </p>
              <ul className="mt-1 space-y-0.5">
                {result.failed.map((cmd, i) => (
                  <li
                    key={i}
                    className="font-mono text-xs text-amber-300/70"
                  >
                    /{cmd}
                  </li>
                ))}
              </ul>
            </div>
          )}
          <p className="mt-2 text-xs text-slate-400">
            Server settings have been saved and will persist across restarts.
          </p>
        </div>
      )}

      {/* Confirmation dialog */}
      {confirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="mx-4 w-full max-w-md rounded-2xl border border-white/[0.08] bg-navy-900 p-6 shadow-2xl">
            <div className="mb-1 text-3xl">{confirm.icon}</div>
            <h3 className="text-lg font-semibold text-white">
              Apply {confirm.name} preset?
            </h3>
            <p className="mt-2 text-sm text-slate-400">
              This will change the following settings on your server:
            </p>
            <div className="mt-3 max-h-48 overflow-y-auto rounded-lg border border-white/[0.06] bg-navy-950/80 p-3">
              <p className="mb-1.5 text-xs font-medium text-slate-300">
                RCON commands:
              </p>
              <ul className="space-y-0.5">
                {confirm.rconCommands.map((cmd, i) => (
                  <li
                    key={i}
                    className="font-mono text-xs text-slate-400"
                  >
                    /{cmd}
                  </li>
                ))}
              </ul>
              {confirm.configKeys.length > 0 && (
                <>
                  <p className="mb-1.5 mt-3 text-xs font-medium text-slate-300">
                    Server properties:
                  </p>
                  <p className="font-mono text-xs text-slate-400">
                    {confirm.configKeys.join(", ")}
                  </p>
                </>
              )}
            </div>
            <p className="mt-3 text-xs text-amber-400/80">
              Current game rules will be overwritten. This does not affect world
              data or installed plugins.
            </p>
            <div className="mt-5 flex gap-3">
              <button
                type="button"
                onClick={() => setConfirm(null)}
                className="flex-1 rounded-lg border border-white/10 px-4 py-2 text-sm font-medium text-slate-300 transition-colors hover:bg-white/[0.05]"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleApply}
                className="flex-1 rounded-lg bg-gradient-to-r from-accent-blue to-brand-500 px-4 py-2 text-sm font-semibold text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.5)] transition-opacity hover:opacity-90"
              >
                Apply preset
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

