"use client";

/**
 * "Game mode — what your players experience": a cinematic card grid, styled
 * after components/customer/freemc/GameTypeGrid.tsx, for one-click Minecraft
 * game-type presets (Skyblock, Prison, KitPvP, ...).
 *
 * Presets have no dedicated hero art yet, so every card falls back to a
 * deterministic brand gradient (same `fallbackGradient` hash as the free-MC
 * grid) keyed by the preset id, rather than shipping an empty box.
 *
 * Applying a preset runs RCON commands immediately and persists a
 * server.properties patch — a real, visible change to the running world — so,
 * like the free-MC grid, selecting a card is a separate step from applying it:
 * the warning copy lives on the confirm bar where it can't be missed.
 */

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  getGameModePresets,
  applyGameModePreset,
  type GameModePresetInfo,
} from "@/lib/actions-game-control";

const PRESETS = getGameModePresets();

/** Deterministic gradient for presets (none have art yet), so the fallback
 *  still looks like a considered card rather than a missing asset. */
function fallbackGradient(key: string): string {
  const palettes = [
    "from-brand-700 via-brand-500 to-accent-blue",
    "from-navy-800 via-brand-600 to-accent-cyan",
    "from-brand-800 via-accent-blue to-brand-400",
  ];
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return palettes[h % palettes.length];
}

export function GameModePresets({
  serverId,
  running,
}: {
  serverId: string;
  running: boolean;
}) {
  const router = useRouter();
  const [selected, setSelected] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<{
    preset: string;
    applied: string[];
    failed: string[];
  } | null>(null);

  const byId = new Map(PRESETS.map((p) => [p.id, p]));
  const pendingPreset = selected ? (byId.get(selected) ?? null) : null;

  function confirm() {
    if (!pendingPreset || pending) return;
    setError(null);
    setResult(null);
    const preset = pendingPreset;
    startTransition(async () => {
      const res = await applyGameModePreset(serverId, preset.id);
      if (res.ok) {
        setResult({ preset: preset.name, applied: res.applied, failed: res.failed });
        setSelected(null);
        router.refresh();
      } else {
        setError(res.error);
      }
    });
  }

  return (
    <div className="card">
      <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
        <h3 className="section-label">
          Game mode <span className="text-slate-600">— what your players experience</span>
        </h3>
        <p className="text-xs text-slate-500">{PRESETS.length} ready-made setups</p>
      </div>
      <p className="mt-2 max-w-2xl text-xs leading-relaxed text-slate-500">
        Applying a preset changes game rules and server settings. It does{" "}
        <strong className="text-slate-400">not</strong> install plugins — install plugins
        from the <span className="text-slate-300">Plugins</span> tab for the full experience.
      </p>

      <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
        {PRESETS.map((preset) => {
          const isSelected = selected === preset.id;
          return (
            <button
              key={preset.id}
              type="button"
              onClick={() => setSelected(preset.id)}
              disabled={pending || !running}
              aria-pressed={isSelected}
              className={`group relative aspect-[4/5] overflow-hidden rounded-2xl border text-left transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-60 ${
                isSelected ? "border-brand-400/70" : "border-white/[0.08] hover:border-brand-400/40"
              }`}
              style={
                isSelected
                  ? { boxShadow: "0 0 0 1px rgb(138 112 251 / 0.45), 0 0 34px -6px rgb(111 71 245 / 0.75)" }
                  : undefined
              }
            >
              <span
                className={`absolute inset-0 bg-gradient-to-br ${fallbackGradient(preset.id)}`}
                aria-hidden
              />

              {/* Scrim: transparent over the art, opaque under the text. */}
              <span
                aria-hidden
                className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-navy-950 via-navy-950/85 to-transparent"
              />

              <span className="absolute left-2.5 top-2.5 text-xl drop-shadow" aria-hidden>
                {preset.icon}
              </span>

              {isSelected && (
                <span className="absolute right-2.5 top-2.5 grid h-8 w-8 place-items-center rounded-full bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow-lg">
                  <svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" aria-hidden>
                    <path
                      d="m5 12.5 4.5 4.5L19 7.5"
                      stroke="currentColor"
                      strokeWidth="3"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </span>
              )}

              <span className="absolute inset-x-0 bottom-0 flex flex-col gap-1 p-3">
                <span className="text-sm font-bold leading-tight text-white drop-shadow">
                  {preset.name}
                </span>
                <span className="line-clamp-2 text-[11px] leading-snug text-slate-300">
                  {preset.description}
                </span>
              </span>
            </button>
          );
        })}
      </div>

      {!running && (
        <p className="mt-3 text-xs text-amber-400/80">Start your server to apply a preset.</p>
      )}

      {error && (
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}

      {pendingPreset && (
        <div className="mt-4 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-amber-400/25 bg-amber-500/[0.07] px-4 py-3.5">
          <div className="min-w-0">
            <p className="text-sm font-semibold text-amber-200">
              Switch to {pendingPreset.name}?
            </p>
            <p className="mt-0.5 text-xs leading-relaxed text-amber-200/70">
              This changes game rules and server settings ({pendingPreset.configKeys.join(", ")}) and
              runs {pendingPreset.rconCommands.length} console commands right away. It does not touch
              your world data or installed plugins.
            </p>
          </div>
          <div className="flex shrink-0 gap-2">
            <button
              type="button"
              className="btn-ghost text-sm"
              onClick={() => setSelected(null)}
              disabled={pending}
            >
              Cancel
            </button>
            <button type="button" className="btn-primary text-sm" onClick={confirm} disabled={pending}>
              {pending ? "Applying…" : "Apply preset"}
            </button>
          </div>
        </div>
      )}

      {result && (
        <div className="mt-4 rounded-lg border border-emerald-500/20 bg-emerald-500/[0.06] px-4 py-3 text-sm">
          <p className="font-medium text-emerald-300">{result.preset} preset applied successfully.</p>
          {result.applied.length > 0 && (
            <div className="mt-2">
              <p className="text-xs font-medium text-emerald-400/80">
                Applied ({result.applied.length}):
              </p>
              <ul className="mt-1 space-y-0.5">
                {result.applied.map((cmd, i) => (
                  <li key={i} className="font-mono text-xs text-emerald-300/70">
                    /{cmd}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {result.failed.length > 0 && (
            <div className="mt-2">
              <p className="text-xs font-medium text-amber-400/80">
                Failed ({result.failed.length}):
              </p>
              <ul className="mt-1 space-y-0.5">
                {result.failed.map((cmd, i) => (
                  <li key={i} className="font-mono text-xs text-amber-300/70">
                    /{cmd}
                  </li>
                ))}
              </ul>
            </div>
          )}
          <p className="mt-2 text-xs text-slate-400">
            Server settings have been saved and will persist across restarts.
          </p>
        </div>
      )}
    </div>
  );
}
